import crypto from 'node:crypto';
import os from 'node:os';
import path from 'node:path';
export function formatLogs(logs) {
    return logs.map(formatLog).join('\n');
}
export function formatLog(log) {
    if (log.detail == null)
        return log.text;
    return [
        `${log.text}; line ${log.detail.line}, column ${log.detail.column} in file ${log.detail.filename}:`,
        log.detail.text,
        log.detail.suggestion,
    ].join('\n');
}
/** Returns a unique temporary filename for an app's generated Blocks shim. */
export function getModuleEntrypoint() {
    return path.join(os.tmpdir(), `blocks-shim-${new Date().toISOString().replaceAll(':', '-')}-${crypto.randomBytes(6).toString('hex')}.tsx`);
}
